<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import { BadgeCheck, CircleHelp, MapPin, Plus, Save } from '@lucide/vue';
import { ref } from 'vue';
import AppShell from '../../Components/AppShell.vue';

type Location = { id: number; code: string; name: string; type: string; address: string | null; phone: string | null; timezone: string; is_active: boolean; assets_count: number };
type Classification = { id: number; code: string; label: string; sort_order: number; is_active: boolean };
type Institution = { id: number; name: string; type: string; email: string | null; phone: string | null; address: string | null; county: string | null; is_active: boolean; customers_count: number; events_count: number };
type Health = { database: string; queueDriver: string; queuedJobs: number | null; failedJobs: number | null; smsConfigured: boolean; smsQueued: number | null; darajaConfigured: boolean; darajaEnvironment: string; backupEncryptionConfigured: boolean; backupExternalDisk: string | null; lastBackupAt: string | null; backupRetentionDays: number; schedulerInstruction: string };
type FeeOverride = { id: number; scope_type: 'product' | 'institution' | 'contract'; scope_id: number | null; scope_reference: string | null; target: string; per_day_amount: string; grace_days: number; cap_amount: string; count_return_day: boolean };
type ProductOption = { id: number; sku: string; name: string };
type TaxCategory = { code: string; label: string; treatment: string; rate: string; effective_from: string; effective_to: string; output_account_code: string; revenue_account_code: string; basis_reference: string; etims_tax_type_code: string; etims_item_code: string; etims_item_class_code: string; etims_packaging_unit_code: string; etims_quantity_unit_code: string };
type ConfigurationMetadata = { record_id: number | null; created_by: number | null; approved_by: number | null; approved_at: string | null; approval_reference: string | null; effective_from: string; review_status: string };
type CutoverSettings = ConfigurationMetadata & { source_snapshot_reference: string; source_snapshot_date: string; proposed_cutover_date: string; candidate_hire_count: number | null; candidate_order_count: number | null; opening_receivables: string; opening_deposits: string; opening_refunds: string; unresolved_exceptions: number | null; finance_reviewer: string; finance_approver_title: string; finance_approval_reference: string; finance_approval_date: string; management_approver: string; management_approval_reference: string; management_approval_date: string; reconciliation_reference: string; backup_restore_reference: string };
type ProviderSettings = ConfigurationMetadata & { techrise_endpoint: string; techrise_sender_id: string; techrise_client_id_configured: boolean; techrise_api_key_configured: boolean; techrise_test_reference: string; techrise_tested_at: string; daraja_enabled: boolean; daraja_environment: string; daraja_transaction_type: string; daraja_consumer_key_configured: boolean; daraja_consumer_secret_configured: boolean; daraja_shortcode_configured: boolean; daraja_passkey_configured: boolean; daraja_callback_token_configured: boolean; daraja_test_reference: string; daraja_tested_at: string; daraja_callback_reference: string };
type DeploymentProfile = ConfigurationMetadata & { deployment_stage: string; aws_region: string; aws_account_alias: string; ec2_reference: string; database_endpoint: string; cache_endpoint: string; application_domain: string; s3_bucket: string; s3_prefix: string; mail_provider: string; mail_from_address: string; backup_retention_days: number | null; rpo_hours: number | null; rto_hours: number | null; support_owner: string; critical_response_hours: number | null; management_release_approver: string; release_approval_reference: string };
const props = defineProps<{ locations: Location[]; institutions: Institution[]; products: ProductOption[]; lateReturnOverrides: FeeOverride[]; classifications: Classification[]; lateReturnPolicy: { per_day_amount: string; grace_days: number; cap_amount: string; count_return_day: boolean }; financeConfigurations: { businessProfile: ConfigurationMetadata & { legal_name: string; trading_name: string; registered_address: string; receipt_phone: string; receipt_email: string; receipt_website: string; receipt_footer: string; kra_pin_configured: boolean }; taxSetup: ConfigurationMetadata & { registration_status: string; vat_effective_date: string; price_mode: string; discount_treatment: string; rounding_mode: string; etims_solution: string; etims_provider: string; etims_live_from: string; etims_branch_id: string; etims_device_serial: string; etims_registrant_name: string; etims_registrant_id: string; etims_receipt_type_code: string; etims_payment_type_code: string; etims_buyer_acceptance: string; accountant_name: string; accountant_approval_reference: string; accountant_approval_date: string; categories: TaxCategory[] }; penaltyAccounting: ConfigurationMetadata & { recognition_basis: string; receivable_account_code: string; penalty_income_account_code: string; waiver_account_code: string; refund_account_code: string; accountant_name: string; approval_reference: string; waiver_branch_limit: number; waiver_finance_limit: number; independent_approval_required: boolean }; historicalCutover: CutoverSettings; providerIntegrations: ProviderSettings; deploymentProfile: DeploymentProfile }; canManageLocations: boolean; canManageClassifications: boolean; actorRole: string; actorId: number; health: Health; app: { name: string; timezone: string; currency: string } }>();
type SettingsCategory = 'organization' | 'policy' | 'finance' | 'system';
const activeSettingsCategory = ref<SettingsCategory>('organization');
const createForm = useForm({ code: '', name: '', type: 'branch', address: '', phone: '', timezone: 'Africa/Nairobi' });
const editingLocationId = ref<number | null>(null);
const editForm = useForm({ name: '', address: '', phone: '', timezone: 'Africa/Nairobi', is_active: true });
const penaltyForm = useForm({ per_day_amount: props.lateReturnPolicy.per_day_amount, grace_days: props.lateReturnPolicy.grace_days, cap_amount: props.lateReturnPolicy.cap_amount, count_return_day: props.lateReturnPolicy.count_return_day });
const businessProfileForm = useForm({ effective_from: props.financeConfigurations.businessProfile.effective_from, legal_name: props.financeConfigurations.businessProfile.legal_name, trading_name: props.financeConfigurations.businessProfile.trading_name, registered_address: props.financeConfigurations.businessProfile.registered_address, receipt_phone: props.financeConfigurations.businessProfile.receipt_phone, receipt_email: props.financeConfigurations.businessProfile.receipt_email, receipt_website: props.financeConfigurations.businessProfile.receipt_website, receipt_footer: props.financeConfigurations.businessProfile.receipt_footer, kra_pin: '' });
const taxSetupForm = useForm({ effective_from: props.financeConfigurations.taxSetup.effective_from, registration_status: props.financeConfigurations.taxSetup.registration_status, vat_effective_date: props.financeConfigurations.taxSetup.vat_effective_date, price_mode: props.financeConfigurations.taxSetup.price_mode, discount_treatment: props.financeConfigurations.taxSetup.discount_treatment, rounding_mode: props.financeConfigurations.taxSetup.rounding_mode, etims_solution: props.financeConfigurations.taxSetup.etims_solution, etims_provider: props.financeConfigurations.taxSetup.etims_provider, etims_live_from: props.financeConfigurations.taxSetup.etims_live_from, etims_branch_id: props.financeConfigurations.taxSetup.etims_branch_id, etims_device_serial: props.financeConfigurations.taxSetup.etims_device_serial, etims_registrant_name: props.financeConfigurations.taxSetup.etims_registrant_name, etims_registrant_id: props.financeConfigurations.taxSetup.etims_registrant_id, etims_receipt_type_code: props.financeConfigurations.taxSetup.etims_receipt_type_code, etims_payment_type_code: props.financeConfigurations.taxSetup.etims_payment_type_code, etims_buyer_acceptance: props.financeConfigurations.taxSetup.etims_buyer_acceptance, accountant_name: props.financeConfigurations.taxSetup.accountant_name, accountant_approval_reference: props.financeConfigurations.taxSetup.accountant_approval_reference, accountant_approval_date: props.financeConfigurations.taxSetup.accountant_approval_date, categories: props.financeConfigurations.taxSetup.categories.map((category) => ({ ...category })) });
const penaltyAccountingForm = useForm({ effective_from: props.financeConfigurations.penaltyAccounting.effective_from, recognition_basis: props.financeConfigurations.penaltyAccounting.recognition_basis, receivable_account_code: props.financeConfigurations.penaltyAccounting.receivable_account_code, penalty_income_account_code: props.financeConfigurations.penaltyAccounting.penalty_income_account_code, waiver_account_code: props.financeConfigurations.penaltyAccounting.waiver_account_code, refund_account_code: props.financeConfigurations.penaltyAccounting.refund_account_code, accountant_name: props.financeConfigurations.penaltyAccounting.accountant_name, approval_reference: props.financeConfigurations.penaltyAccounting.approval_reference, waiver_branch_limit: props.financeConfigurations.penaltyAccounting.waiver_branch_limit, waiver_finance_limit: props.financeConfigurations.penaltyAccounting.waiver_finance_limit, independent_approval_required: props.financeConfigurations.penaltyAccounting.independent_approval_required });
const cutoverForm = useForm({ effective_from: props.financeConfigurations.historicalCutover.effective_from, source_snapshot_reference: props.financeConfigurations.historicalCutover.source_snapshot_reference, source_snapshot_date: props.financeConfigurations.historicalCutover.source_snapshot_date, proposed_cutover_date: props.financeConfigurations.historicalCutover.proposed_cutover_date, candidate_hire_count: props.financeConfigurations.historicalCutover.candidate_hire_count, candidate_order_count: props.financeConfigurations.historicalCutover.candidate_order_count, opening_receivables: props.financeConfigurations.historicalCutover.opening_receivables, opening_deposits: props.financeConfigurations.historicalCutover.opening_deposits, opening_refunds: props.financeConfigurations.historicalCutover.opening_refunds, unresolved_exceptions: props.financeConfigurations.historicalCutover.unresolved_exceptions, finance_reviewer: props.financeConfigurations.historicalCutover.finance_reviewer, finance_approver_title: props.financeConfigurations.historicalCutover.finance_approver_title, finance_approval_reference: props.financeConfigurations.historicalCutover.finance_approval_reference, finance_approval_date: props.financeConfigurations.historicalCutover.finance_approval_date, management_approver: props.financeConfigurations.historicalCutover.management_approver, management_approval_reference: props.financeConfigurations.historicalCutover.management_approval_reference, management_approval_date: props.financeConfigurations.historicalCutover.management_approval_date, reconciliation_reference: props.financeConfigurations.historicalCutover.reconciliation_reference, backup_restore_reference: props.financeConfigurations.historicalCutover.backup_restore_reference });
const providerForm = useForm({ techrise_endpoint: props.financeConfigurations.providerIntegrations.techrise_endpoint, techrise_client_id: '', techrise_api_key: '', techrise_sender_id: props.financeConfigurations.providerIntegrations.techrise_sender_id, techrise_test_reference: props.financeConfigurations.providerIntegrations.techrise_test_reference, techrise_tested_at: props.financeConfigurations.providerIntegrations.techrise_tested_at, daraja_enabled: props.financeConfigurations.providerIntegrations.daraja_enabled, daraja_environment: props.financeConfigurations.providerIntegrations.daraja_environment, daraja_consumer_key: '', daraja_consumer_secret: '', daraja_shortcode: '', daraja_passkey: '', daraja_callback_token: '', daraja_transaction_type: props.financeConfigurations.providerIntegrations.daraja_transaction_type, daraja_test_reference: props.financeConfigurations.providerIntegrations.daraja_test_reference, daraja_tested_at: props.financeConfigurations.providerIntegrations.daraja_tested_at, daraja_callback_reference: props.financeConfigurations.providerIntegrations.daraja_callback_reference });
const deploymentForm = useForm({ effective_from: props.financeConfigurations.deploymentProfile.effective_from, deployment_stage: props.financeConfigurations.deploymentProfile.deployment_stage, aws_region: props.financeConfigurations.deploymentProfile.aws_region, aws_account_alias: props.financeConfigurations.deploymentProfile.aws_account_alias, ec2_reference: props.financeConfigurations.deploymentProfile.ec2_reference, database_endpoint: props.financeConfigurations.deploymentProfile.database_endpoint, cache_endpoint: props.financeConfigurations.deploymentProfile.cache_endpoint, application_domain: props.financeConfigurations.deploymentProfile.application_domain, s3_bucket: props.financeConfigurations.deploymentProfile.s3_bucket, s3_prefix: props.financeConfigurations.deploymentProfile.s3_prefix, mail_provider: props.financeConfigurations.deploymentProfile.mail_provider, mail_from_address: props.financeConfigurations.deploymentProfile.mail_from_address, backup_retention_days: props.financeConfigurations.deploymentProfile.backup_retention_days, rpo_hours: props.financeConfigurations.deploymentProfile.rpo_hours, rto_hours: props.financeConfigurations.deploymentProfile.rto_hours, support_owner: props.financeConfigurations.deploymentProfile.support_owner, critical_response_hours: props.financeConfigurations.deploymentProfile.critical_response_hours, management_release_approver: props.financeConfigurations.deploymentProfile.management_release_approver, release_approval_reference: props.financeConfigurations.deploymentProfile.release_approval_reference });
const approvalForm = useForm({ approval_reference: '', confirm: true });
const overrideForm = useForm({ scope_type: 'product' as FeeOverride['scope_type'], scope_id: '', scope_reference: '', per_day_amount: '', grace_days: 0, cap_amount: '0.00', count_return_day: false });
const editingOverrideId = ref<number | null>(null);
const classificationEditId = ref<number | null>(null);
const classificationForm = useForm({ label: '', sort_order: 0, is_active: true });
function createLocation(): void { createForm.post('/settings/locations', { preserveScroll: true, onSuccess: () => createForm.reset() }); }
function beginEdit(location: Location): void {
    editingLocationId.value = location.id;
    editForm.name = location.name;
    editForm.address = location.address ?? '';
    editForm.phone = location.phone ?? '';
    editForm.timezone = location.timezone;
    editForm.is_active = location.is_active;
}
function saveLocation(): void {
    if (editingLocationId.value === null) return;
    editForm.patch(`/settings/locations/${editingLocationId.value}`, { preserveScroll: true, onSuccess: () => { editingLocationId.value = null; } });
}
function savePenaltyPolicy(): void { penaltyForm.put('/settings/late-return-policy', { preserveScroll: true }); }
function saveBusinessProfile(): void { businessProfileForm.put('/settings/finance/business-profile', { preserveScroll: true, onSuccess: () => businessProfileForm.reset('kra_pin') }); }
function saveTaxSetup(): void { taxSetupForm.put('/settings/finance/tax-setup', { preserveScroll: true }); }
function savePenaltyAccounting(): void { penaltyAccountingForm.put('/settings/finance/penalty-accounting', { preserveScroll: true }); }
function saveCutover(): void { cutoverForm.put('/settings/finance/historical-cutover', { preserveScroll: true }); }
function saveProviders(): void { providerForm.put('/settings/finance/provider-integrations', { preserveScroll: true, onSuccess: () => providerForm.reset('techrise_client_id', 'techrise_api_key', 'daraja_consumer_key', 'daraja_consumer_secret', 'daraja_shortcode', 'daraja_passkey', 'daraja_callback_token') }); }
function saveDeployment(): void { deploymentForm.put('/settings/finance/deployment-profile', { preserveScroll: true }); }
function approveConfiguration(section: string, configuration: ConfigurationMetadata): void {
    if (configuration.record_id === null || configuration.created_by === props.actorId) return;
    approvalForm.post(`/settings/finance/${section}/${configuration.record_id}/approve`, { preserveScroll: true });
}
function canApprove(configuration: ConfigurationMetadata, allowFinance = true): boolean {
    return configuration.review_status === 'draft' && configuration.record_id !== null && configuration.created_by !== props.actorId && (props.actorRole !== 'finance' || allowFinance);
}
function addTaxCategory(): void { taxSetupForm.categories.push({ code: '', label: '', treatment: 'unconfigured', rate: '', effective_from: '', effective_to: '', output_account_code: '', revenue_account_code: '', basis_reference: '', etims_tax_type_code: '', etims_item_code: '', etims_item_class_code: '', etims_packaging_unit_code: '', etims_quantity_unit_code: '' }); }
function removeTaxCategory(index: number): void { if (taxSetupForm.categories.length > 1) taxSetupForm.categories.splice(index, 1); }
function resetOverrideForm(): void {
    editingOverrideId.value = null;
    overrideForm.reset();
    overrideForm.scope_type = 'product';
    overrideForm.cap_amount = '0.00';
}
function saveOverride(): void {
    overrideForm.transform((data) => ({
        ...data,
        scope_id: data.scope_type === 'contract' ? null : data.scope_id || null,
        scope_reference: data.scope_type === 'contract' ? data.scope_reference.trim().toUpperCase() : null,
    }));
    overrideForm.put('/settings/late-return-policy-overrides', { preserveScroll: true, onSuccess: resetOverrideForm });
}
function editOverride(policy: FeeOverride): void {
    editingOverrideId.value = policy.id;
    overrideForm.scope_type = policy.scope_type;
    overrideForm.scope_id = policy.scope_id === null ? '' : String(policy.scope_id);
    overrideForm.scope_reference = policy.scope_reference ?? '';
    overrideForm.per_day_amount = policy.per_day_amount;
    overrideForm.grace_days = policy.grace_days;
    overrideForm.cap_amount = policy.cap_amount;
    overrideForm.count_return_day = policy.count_return_day;
}
function removeOverride(policy: FeeOverride): void {
    overrideForm.delete(`/settings/late-return-policy-overrides/${policy.id}`, { preserveScroll: true, onSuccess: resetOverrideForm });
}
function beginClassificationEdit(classification: Classification): void {
    classificationEditId.value = classification.id;
    classificationForm.label = classification.label;
    classificationForm.sort_order = classification.sort_order;
    classificationForm.is_active = classification.is_active;
}
function saveClassification(): void {
    if (classificationEditId.value === null) return;
    classificationForm.patch(`/settings/academic-classifications/${classificationEditId.value}`, { preserveScroll: true, onSuccess: () => { classificationEditId.value = null; } });
}
</script>

<template>
    <Head title="Settings" />
    <AppShell active="settings">
        <div class="page-heading"><div><h1>Settings</h1><p>Manage your organization, policies, finance and system setup.</p></div></div>
        <div v-if="activeSettingsCategory === 'organization'" class="workflow-note"><UserRoundCog :size="16" aria-hidden="true" /> New staff receive a one-time password setup link by email. The link expires automatically and can be reissued through Forgot password.</div>
        <nav class="settings-nav" aria-label="Settings categories">
            <section class="settings-nav-group" aria-labelledby="user-settings-label">
                <header class="settings-nav-heading"><h2 id="user-settings-label">User settings</h2><details class="settings-group-help"><summary aria-label="About user settings"><CircleHelp :size="15" aria-hidden="true" /></summary><span class="settings-group-tooltip" role="tooltip">Manage your organization, locations, staff access and account security.</span></details></header>
                <div class="settings-nav-options">
                    <button type="button" :class="{ active: activeSettingsCategory === 'organization' }" :aria-pressed="activeSettingsCategory === 'organization'" @click="activeSettingsCategory = 'organization'">Organization &amp; access</button>
                    <Link href="/account/security">Account security</Link>
                </div>
            </section>
            <section class="settings-nav-group" aria-labelledby="technical-settings-label">
                <header class="settings-nav-heading"><h2 id="technical-settings-label">Technical settings</h2><details class="settings-group-help"><summary aria-label="About technical settings"><CircleHelp :size="15" aria-hidden="true" /></summary><span class="settings-group-tooltip" role="tooltip">Set operating rules, finance compliance, integrations and recovery details.</span></details></header>
                <div class="settings-nav-options">
                    <button type="button" :class="{ active: activeSettingsCategory === 'policy' }" :aria-pressed="activeSettingsCategory === 'policy'" @click="activeSettingsCategory = 'policy'">Operating policies</button>
                    <button type="button" :class="{ active: activeSettingsCategory === 'finance' }" :aria-pressed="activeSettingsCategory === 'finance'" @click="activeSettingsCategory = 'finance'">Finance &amp; compliance</button>
                    <button type="button" :class="{ active: activeSettingsCategory === 'system' }" :aria-pressed="activeSettingsCategory === 'system'" @click="activeSettingsCategory = 'system'">Integrations &amp; recovery</button>
                </div>
            </section>
        </nav>
        <section v-if="activeSettingsCategory === 'organization'" id="organization-settings" class="settings-group" aria-labelledby="organization-settings-title">
            <header class="settings-group-heading">
                <div><h2 id="organization-settings-title" class="settings-group-title">Organization &amp; access</h2><p class="settings-group-description">Company identity, locations, academic partners and staff permissions.</p></div>
                <details class="settings-group-help"><summary aria-label="About organization and access settings" aria-describedby="organization-settings-tooltip"><CircleHelp :size="17" aria-hidden="true" /></summary><span id="organization-settings-tooltip" class="settings-group-tooltip" role="tooltip">Set up the places and people that use GOWNSEA. Location assignments also control stock custody and staff visibility.</span></details>
            </header>
        <section v-if="canManageLocations" class="panel settings-block">
            <div class="settings-title"><Plus aria-hidden="true" /><div><h2 class="panel-title">Add a warehouse or branch</h2><p class="panel-subtitle">Location codes are permanent references used by stock, staff assignments and transfer history.</p></div></div>
            <form class="location-form" @submit.prevent="createLocation">
                <div class="form-field"><label for="location-code">Location code</label><input id="location-code" v-model="createForm.code" class="field" required maxlength="32" placeholder="e.g. NAIROBI-BR"></div>
                <div class="form-field"><label for="location-name">Location name</label><input id="location-name" v-model="createForm.name" class="field" required maxlength="255"></div>
                <div class="form-field"><label for="location-type">Type</label><select id="location-type" v-model="createForm.type" class="select-field"><option value="branch">Branch</option><option value="warehouse">Warehouse</option></select></div>
                <div class="form-field"><label for="location-phone">Phone</label><input id="location-phone" v-model="createForm.phone" class="field" type="tel" placeholder="0712 345 678"></div>
                <div class="form-field"><label for="location-timezone">Timezone</label><input id="location-timezone" v-model="createForm.timezone" class="field" required placeholder="Africa/Nairobi"></div>
                <div class="form-field"><label for="location-address">Address</label><input id="location-address" v-model="createForm.address" class="field" maxlength="255"></div>
                <small v-for="(message, field) in createForm.errors" :key="field" class="form-error">{{ message }}</small>
                <div class="form-actions"><button class="primary-button" type="submit" :disabled="createForm.processing"><Plus aria-hidden="true" /> {{ createForm.processing ? 'Saving…' : 'Add location' }}</button></div>
            </form>
        </section>
        <section class="panel settings-block"><div class="settings-title"><MapPin aria-hidden="true" /><div><h2 class="panel-title">Warehouses & branches</h2><p class="panel-subtitle">Location assignments define staff visibility and stock custody.</p></div></div>
            <div v-if="locations.length" class="settings-table-wrap"><table class="data-table"><thead><tr><th>Location</th><th>Code</th><th>Type</th><th>Address</th><th>Timezone</th><th>Current assets</th><th>Status</th><th v-if="canManageLocations">Manage</th></tr></thead><tbody><template v-for="location in locations" :key="location.id"><tr><td><strong>{{ location.name }}</strong></td><td>{{ location.code }}</td><td>{{ location.type }}</td><td>{{ location.address ?? '—' }}</td><td>{{ location.timezone }}</td><td>{{ location.assets_count.toLocaleString() }}</td><td><span class="status-chip" :class="location.is_active ? 'completed' : 'damaged'">{{ location.is_active ? 'Active' : 'Inactive' }}</span></td><td v-if="canManageLocations"><button class="secondary-link compact-action" type="button" @click="beginEdit(location)">{{ editingLocationId === location.id ? 'Editing…' : 'Edit' }}</button></td></tr><tr v-if="editingLocationId === location.id && canManageLocations"><td colspan="8"><form class="location-edit-form" @submit.prevent="saveLocation"><div class="form-field"><label :for="`edit-name-${location.id}`">Name</label><input :id="`edit-name-${location.id}`" v-model="editForm.name" class="field" required maxlength="255"></div><div class="form-field"><label :for="`edit-address-${location.id}`">Address</label><input :id="`edit-address-${location.id}`" v-model="editForm.address" class="field" maxlength="255"></div><div class="form-field"><label :for="`edit-phone-${location.id}`">Phone</label><input :id="`edit-phone-${location.id}`" v-model="editForm.phone" class="field" type="tel"></div><div class="form-field"><label :for="`edit-timezone-${location.id}`">Timezone</label><input :id="`edit-timezone-${location.id}`" v-model="editForm.timezone" class="field" required></div><label class="location-active"><input v-model="editForm.is_active" type="checkbox"> Active</label><div class="form-field"><small v-for="(message, field) in editForm.errors" :key="field" class="form-error">{{ message }}</small></div><button class="primary-button" type="submit" :disabled="editForm.processing"><Save aria-hidden="true" /> {{ editForm.processing ? 'Saving…' : 'Save changes' }}</button><button class="secondary-link" type="button" @click="editingLocationId = null">Cancel</button></form></td></tr></template></tbody></table></div>
            <div v-else class="empty-state"><div><MapPin aria-hidden="true" /><strong>No locations configured</strong><span>Run the database seeder to add the central warehouse.</span></div></div>
        </section>
                <section class="panel settings-block"><div class="settings-title"><BadgeCheck aria-hidden="true" /><div><h2 class="panel-title">Academic gown classifications</h2><p class="panel-subtitle">Stable identifiers keep historical data intact. Super administrators can change display labels, order and availability.</p></div></div>
            <div class="classification-grid"><article v-for="classification in classifications" :key="classification.code" class="classification-card"><small>{{ classification.code }}</small><strong>{{ classification.label }}</strong><span>{{ classification.is_active ? 'Active' : 'Inactive' }}</span><button v-if="canManageClassifications" class="secondary-link compact-action" type="button" @click="beginClassificationEdit(classification)">{{ classificationEditId === classification.id ? 'Editing…' : 'Configure' }}</button><form v-if="classificationEditId === classification.id && canManageClassifications" class="classification-edit" @submit.prevent="saveClassification"><label :for="`classification-label-${classification.id}`">Display label</label><input :id="`classification-label-${classification.id}`" v-model="classificationForm.label" class="field" maxlength="100" required><label :for="`classification-order-${classification.id}`">Display order</label><input :id="`classification-order-${classification.id}`" v-model.number="classificationForm.sort_order" class="field" type="number" min="0" max="65535" required><label class="location-active"><input v-model="classificationForm.is_active" type="checkbox"> Available for new products</label><small v-for="(message, field) in classificationForm.errors" :key="field" class="form-error">{{ message }}</small><div class="form-actions"><button class="secondary-link" type="button" @click="classificationEditId = null">Cancel</button><button class="primary-button" type="submit" :disabled="classificationForm.processing">Save</button></div></form></article></div>
        </section>
        <section class="panel company-panel"><h2 class="panel-title">Company defaults</h2><div class="company-grid"><span>Company name</span><strong>{{ app.name }}</strong><span>Timezone</span><strong>{{ app.timezone }}</strong><span>Currency</span><strong>{{ app.currency }}</strong></div></section>
        </section>
        <section v-if="activeSettingsCategory === 'policy'" id="policy-settings" class="settings-group" aria-labelledby="policy-settings-title">
            <header class="settings-group-heading">
                <div><h2 id="policy-settings-title" class="settings-group-title">Operating policies</h2><p class="settings-group-description">Set the rules used for hires and late returns.</p></div>
                <details class="settings-group-help"><summary aria-label="About operating policies" aria-describedby="policy-settings-tooltip"><CircleHelp :size="17" aria-hidden="true" /></summary><span id="policy-settings-tooltip" class="settings-group-tooltip" role="tooltip">Policy changes apply to new hires. Existing hires keep the terms recorded when they were created.</span></details>
            </header>
        <section class="panel settings-block"><div class="settings-title"><BadgeCheck aria-hidden="true" /><div><h2 class="panel-title">Late return policy</h2><p class="panel-subtitle">Amounts are in KES. Policy is snapshotted when a hire is issued or reserved; changes apply to new hires.</p></div></div>
            <form class="penalty-form" @submit.prevent="savePenaltyPolicy">
                <div class="form-field"><label for="penalty-rate">Daily late fee</label><input id="penalty-rate" v-model="penaltyForm.per_day_amount" class="field" inputmode="decimal" required><small v-if="penaltyForm.errors.per_day_amount" class="form-error">{{ penaltyForm.errors.per_day_amount }}</small></div>
                <div class="form-field"><label for="penalty-grace">Grace days</label><input id="penalty-grace" v-model.number="penaltyForm.grace_days" class="field" type="number" min="0" max="365" required><small v-if="penaltyForm.errors.grace_days" class="form-error">{{ penaltyForm.errors.grace_days }}</small></div>
                <div class="form-field"><label for="penalty-cap">Maximum late fee (0 = uncapped)</label><input id="penalty-cap" v-model="penaltyForm.cap_amount" class="field" inputmode="decimal" required><small v-if="penaltyForm.errors.cap_amount" class="form-error">{{ penaltyForm.errors.cap_amount }}</small></div>
                <label class="location-active"><input v-model="penaltyForm.count_return_day" type="checkbox"> Include the return date as a billable day</label>
                <div class="form-actions"><button class="primary-button" type="submit" :disabled="penaltyForm.processing"><Save aria-hidden="true" /> {{ penaltyForm.processing ? 'Saving…' : 'Save late return policy' }}</button></div>
            </form>
            <div class="override-heading"><h3>Scoped fee overrides</h3><p>More specific rules take precedence in this order: contract, product, institution, then the default above.</p></div>
            <form class="override-form" @submit.prevent="saveOverride">
                <div class="form-field"><label for="override-type">Applies to</label><select id="override-type" v-model="overrideForm.scope_type" class="select-field"><option value="product">Product</option><option value="institution">Institution</option><option value="contract">Contract reference</option></select></div>
                <div v-if="overrideForm.scope_type === 'product'" class="form-field"><label for="override-product">Product</label><select id="override-product" v-model="overrideForm.scope_id" class="select-field" required><option value="">Choose a product</option><option v-for="product in products" :key="product.id" :value="String(product.id)">{{ product.name }} · {{ product.sku }}</option></select><small v-if="overrideForm.errors.scope_id" class="form-error">{{ overrideForm.errors.scope_id }}</small></div>
                <div v-else-if="overrideForm.scope_type === 'institution'" class="form-field"><label for="override-institution">Institution</label><select id="override-institution" v-model="overrideForm.scope_id" class="select-field" required><option value="">Choose an institution</option><option v-for="institution in institutions.filter((item) => item.is_active)" :key="institution.id" :value="String(institution.id)">{{ institution.name }}</option></select><small v-if="overrideForm.errors.scope_id" class="form-error">{{ overrideForm.errors.scope_id }}</small></div>
                <div v-else class="form-field"><label for="override-contract">Contract reference</label><input id="override-contract" v-model="overrideForm.scope_reference" class="field" maxlength="100" required placeholder="e.g. EDU-2026-01"><small v-if="overrideForm.errors.scope_reference" class="form-error">{{ overrideForm.errors.scope_reference }}</small></div>
                <div class="form-field"><label for="override-rate">Daily fee (KES)</label><input id="override-rate" v-model="overrideForm.per_day_amount" class="field" inputmode="decimal" required><small v-if="overrideForm.errors.per_day_amount" class="form-error">{{ overrideForm.errors.per_day_amount }}</small></div>
                <div class="form-field"><label for="override-grace">Grace days</label><input id="override-grace" v-model.number="overrideForm.grace_days" class="field" type="number" min="0" max="365" required><small v-if="overrideForm.errors.grace_days" class="form-error">{{ overrideForm.errors.grace_days }}</small></div>
                <div class="form-field"><label for="override-cap">Maximum fee (0 = uncapped)</label><input id="override-cap" v-model="overrideForm.cap_amount" class="field" inputmode="decimal" required><small v-if="overrideForm.errors.cap_amount" class="form-error">{{ overrideForm.errors.cap_amount }}</small></div>
                <label class="location-active"><input v-model="overrideForm.count_return_day" type="checkbox"> Include return date as a billable day</label>
                <small v-if="overrideForm.errors.scope_type" class="form-error">{{ overrideForm.errors.scope_type }}</small>
                <div class="form-actions"><button class="primary-button" type="submit" :disabled="overrideForm.processing"><Save aria-hidden="true" /> {{ overrideForm.processing ? 'Saving…' : editingOverrideId ? 'Update override' : 'Save override' }}</button><button v-if="editingOverrideId" class="secondary-link" type="button" @click="resetOverrideForm">Cancel edit</button></div>
            </form>
            <div v-if="lateReturnOverrides.length" class="settings-table-wrap override-table"><table class="data-table"><thead><tr><th>Applies to</th><th>Target</th><th>Daily fee</th><th>Grace</th><th>Cap</th><th>Return day</th><th>Manage</th></tr></thead><tbody><tr v-for="policy in lateReturnOverrides" :key="policy.id"><td>{{ policy.scope_type }}</td><td>{{ policy.target }}</td><td>KES {{ policy.per_day_amount }}</td><td>{{ policy.grace_days }} days</td><td>{{ Number(policy.cap_amount) === 0 ? 'Uncapped' : `KES ${policy.cap_amount}` }}</td><td>{{ policy.count_return_day ? 'Included' : 'Excluded' }}</td><td class="override-actions"><button class="secondary-link compact-action" type="button" @click="editOverride(policy)">Edit</button><button class="secondary-link compact-action" type="button" :disabled="overrideForm.processing" @click="removeOverride(policy)">Remove</button></td></tr></tbody></table></div>
            <div v-else class="empty-state override-empty"><div><BadgeCheck aria-hidden="true" /><strong>No scoped fee rules</strong><span>New hires use the default policy above.</span></div></div>
        </section>
        </section>
        <section v-if="activeSettingsCategory === 'finance'" id="finance-settings" class="settings-group" aria-labelledby="finance-settings-title">
            <header class="settings-group-heading">
                <div><h2 id="finance-settings-title" class="settings-group-title">Finance &amp; compliance</h2><p class="settings-group-description">Maintain review drafts for tax, accounting and historical cutover.</p></div>
                <details class="settings-group-help"><summary aria-label="About finance and compliance settings" aria-describedby="finance-settings-tooltip"><CircleHelp :size="17" aria-hidden="true" /></summary><span id="finance-settings-tooltip" class="settings-group-tooltip" role="tooltip">These records support finance review and approvals. Draft values do not change invoices or post accounting entries until approved.</span></details>
            </header>
        <section class="panel settings-block">
            <div class="settings-title"><BadgeCheck aria-hidden="true" /><div><h2 class="panel-title">Business and tax profile</h2><p class="panel-subtitle">Maintain the registered business identity, receipt contact details, and tax schedule. Business profile changes appear on receipt downloads after independent approval; tax settings remain review drafts until connected to invoice calculations.</p></div></div>
            <div class="configuration-status"><strong>{{ financeConfigurations.businessProfile.review_status.replaceAll('_', ' ') }}</strong><span>Effective from {{ financeConfigurations.businessProfile.effective_from || 'not set' }}</span><span v-if="financeConfigurations.businessProfile.kra_pin_configured">KRA PIN is stored encrypted. Its value is never displayed.</span></div>
            <form class="finance-config-grid" @submit.prevent="saveBusinessProfile">
                <div class="form-field"><label for="business-legal-name">Registered legal name</label><input id="business-legal-name" v-model="businessProfileForm.legal_name" class="field" maxlength="255"><small v-if="businessProfileForm.errors.legal_name" class="form-error">{{ businessProfileForm.errors.legal_name }}</small></div>
                <div class="form-field"><label for="business-trading-name">Trading name</label><input id="business-trading-name" v-model="businessProfileForm.trading_name" class="field" maxlength="255"><small v-if="businessProfileForm.errors.trading_name" class="form-error">{{ businessProfileForm.errors.trading_name }}</small></div>
                <div class="form-field"><label for="business-effective-date">Profile effective date</label><input id="business-effective-date" v-model="businessProfileForm.effective_from" class="field" type="date"><small v-if="businessProfileForm.errors.effective_from" class="form-error">{{ businessProfileForm.errors.effective_from }}</small></div>
                <div class="form-field full"><label for="business-registered-address">Registered address</label><textarea id="business-registered-address" v-model="businessProfileForm.registered_address" class="field" rows="2" maxlength="1000"></textarea><small v-if="businessProfileForm.errors.registered_address" class="form-error">{{ businessProfileForm.errors.registered_address }}</small></div>
                <div class="form-field"><label for="business-receipt-phone">Receipt contact phone</label><input id="business-receipt-phone" v-model="businessProfileForm.receipt_phone" class="field" type="tel" maxlength="32" placeholder="e.g. +254 700 000 000"><small v-if="businessProfileForm.errors.receipt_phone" class="form-error">{{ businessProfileForm.errors.receipt_phone }}</small></div>
                <div class="form-field"><label for="business-receipt-email">Receipt contact email</label><input id="business-receipt-email" v-model="businessProfileForm.receipt_email" class="field" type="email" maxlength="255" placeholder="accounts@example.com"><small v-if="businessProfileForm.errors.receipt_email" class="form-error">{{ businessProfileForm.errors.receipt_email }}</small></div>
                <div class="form-field"><label for="business-receipt-website">Website</label><input id="business-receipt-website" v-model="businessProfileForm.receipt_website" class="field" type="url" maxlength="255" placeholder="https://example.com"><small v-if="businessProfileForm.errors.receipt_website" class="form-error">{{ businessProfileForm.errors.receipt_website }}</small></div>
                <div class="form-field full"><label for="business-receipt-footer">Receipt footer message</label><textarea id="business-receipt-footer" v-model="businessProfileForm.receipt_footer" class="field" rows="2" maxlength="500" placeholder="Optional thank-you message or payment terms"></textarea><small>This appears on standard and thermal receipts. Branch address and phone come from each location’s settings.</small><small v-if="businessProfileForm.errors.receipt_footer" class="form-error">{{ businessProfileForm.errors.receipt_footer }}</small></div>
                <div class="form-field"><label for="business-kra-pin">KRA PIN</label><input id="business-kra-pin" v-model="businessProfileForm.kra_pin" class="field" maxlength="64" autocomplete="off" placeholder="Leave blank to keep the saved value"><small>Encrypted at rest; excluded from audit logs and page responses.</small><small v-if="businessProfileForm.errors.kra_pin" class="form-error">{{ businessProfileForm.errors.kra_pin }}</small></div>
                <div class="form-actions"><button class="primary-button" type="submit" :disabled="businessProfileForm.processing"><Save aria-hidden="true" />{{ businessProfileForm.processing ? 'Saving…' : 'Save profile draft' }}</button></div>
            </form>
            <div v-if="canApprove(financeConfigurations.businessProfile, false)" class="approval-row"><div class="form-field"><label for="business-profile-approval-reference">Independent reviewer evidence reference</label><input id="business-profile-approval-reference" v-model="approvalForm.approval_reference" class="field" maxlength="255" required></div><button class="primary-button" type="button" :disabled="approvalForm.processing" @click="approveConfiguration('business-profile', financeConfigurations.businessProfile)">Approve profile</button></div>
            <div class="override-heading"><h3>Tax and statutory setup</h3><p>Use accountant-approved categories and effective dates. Tax remains disabled in customer documents until this schedule is reviewed and connected to invoice calculations.</p></div>
            <div class="configuration-status"><strong>{{ financeConfigurations.taxSetup.review_status.replaceAll('_', ' ') }}</strong><span>Effective from {{ financeConfigurations.taxSetup.effective_from || 'not set' }}</span></div>
            <form class="finance-config-grid" @submit.prevent="saveTaxSetup">
                <div class="form-field"><label for="tax-effective-date">Setup effective date</label><input id="tax-effective-date" v-model="taxSetupForm.effective_from" class="field" type="date"><small v-if="taxSetupForm.errors.effective_from" class="form-error">{{ taxSetupForm.errors.effective_from }}</small></div>
                <div class="form-field"><label for="tax-registration-status">VAT registration</label><select id="tax-registration-status" v-model="taxSetupForm.registration_status" class="select-field"><option value="unknown">Not confirmed</option><option value="vat_registered">Registered</option><option value="not_vat_registered">Not registered</option></select><small v-if="taxSetupForm.errors.registration_status" class="form-error">{{ taxSetupForm.errors.registration_status }}</small></div>
                <div class="form-field"><label for="tax-vat-effective-date">VAT effective date</label><input id="tax-vat-effective-date" v-model="taxSetupForm.vat_effective_date" class="field" type="date"><small v-if="taxSetupForm.errors.vat_effective_date" class="form-error">{{ taxSetupForm.errors.vat_effective_date }}</small></div>
                <div class="form-field"><label for="tax-price-mode">Customer price display</label><select id="tax-price-mode" v-model="taxSetupForm.price_mode" class="select-field"><option value="not_configured">Not configured</option><option value="inclusive">Tax inclusive</option><option value="exclusive">Tax exclusive</option></select><small v-if="taxSetupForm.errors.price_mode" class="form-error">{{ taxSetupForm.errors.price_mode }}</small></div>
                <div class="form-field"><label for="tax-discount-treatment">Discount treatment</label><select id="tax-discount-treatment" v-model="taxSetupForm.discount_treatment" class="select-field"><option value="not_configured">Not configured</option><option value="before_tax">Before tax</option><option value="after_tax">After tax</option></select><small v-if="taxSetupForm.errors.discount_treatment" class="form-error">{{ taxSetupForm.errors.discount_treatment }}</small></div>
                <div class="form-field"><label for="tax-rounding-mode">Tax rounding</label><select id="tax-rounding-mode" v-model="taxSetupForm.rounding_mode" class="select-field"><option value="not_configured">Not configured</option><option value="line">Per line</option><option value="invoice">Per invoice</option></select><small v-if="taxSetupForm.errors.rounding_mode" class="form-error">{{ taxSetupForm.errors.rounding_mode }}</small></div>
                <div class="form-field"><label for="etims-solution">eTIMS solution</label><select id="etims-solution" v-model="taxSetupForm.etims_solution" class="select-field"><option value="unselected">Not selected</option><option value="kra">KRA OSCU/VSCU system integration</option><option value="third_party">Third-party integrator</option><option value="none">No eTIMS integration</option></select><small v-if="taxSetupForm.errors.etims_solution" class="form-error">{{ taxSetupForm.errors.etims_solution }}</small></div>
                <div v-if="taxSetupForm.etims_solution === 'third_party'" class="form-field"><label for="etims-provider">eTIMS provider</label><input id="etims-provider" v-model="taxSetupForm.etims_provider" class="field" maxlength="255"><small v-if="taxSetupForm.errors.etims_provider" class="form-error">{{ taxSetupForm.errors.etims_provider }}</small></div>
                <template v-if="taxSetupForm.etims_solution === 'kra'">
                    <p class="form-note full-width">KRA system integration stays disabled until the approved taxpayer VSCU bridge endpoint is supplied in deployment secrets and KRA has certified the integration.</p>
                    <div class="form-field"><label for="etims-live-from">eTIMS go-live date</label><input id="etims-live-from" v-model="taxSetupForm.etims_live_from" class="field" type="date"><small>Earlier invoices are held for cutover review and are never sent automatically.</small><small v-if="taxSetupForm.errors.etims_live_from" class="form-error">{{ taxSetupForm.errors.etims_live_from }}</small></div>
                    <div class="form-field"><label for="etims-branch-id">KRA branch ID</label><input id="etims-branch-id" v-model="taxSetupForm.etims_branch_id" class="field" maxlength="2" autocomplete="off"><small v-if="taxSetupForm.errors.etims_branch_id" class="form-error">{{ taxSetupForm.errors.etims_branch_id }}</small></div>
                    <div class="form-field"><label for="etims-device-serial">Registered device serial</label><input id="etims-device-serial" v-model="taxSetupForm.etims_device_serial" class="field" maxlength="64" autocomplete="off"><small v-if="taxSetupForm.errors.etims_device_serial" class="form-error">{{ taxSetupForm.errors.etims_device_serial }}</small></div>
                    <div class="form-field"><label for="etims-registrant-name">Registered operator name</label><input id="etims-registrant-name" v-model="taxSetupForm.etims_registrant_name" class="field" maxlength="60"><small v-if="taxSetupForm.errors.etims_registrant_name" class="form-error">{{ taxSetupForm.errors.etims_registrant_name }}</small></div>
                    <div class="form-field"><label for="etims-registrant-id">Registered operator ID</label><input id="etims-registrant-id" v-model="taxSetupForm.etims_registrant_id" class="field" maxlength="20"><small v-if="taxSetupForm.errors.etims_registrant_id" class="form-error">{{ taxSetupForm.errors.etims_registrant_id }}</small></div>
                    <div class="form-field"><label for="etims-receipt-type">Receipt type code</label><input id="etims-receipt-type" v-model="taxSetupForm.etims_receipt_type_code" class="field" maxlength="5" placeholder="Use the approved KRA code"><small v-if="taxSetupForm.errors.etims_receipt_type_code" class="form-error">{{ taxSetupForm.errors.etims_receipt_type_code }}</small></div>
                    <div class="form-field"><label for="etims-payment-type">Payment type code</label><input id="etims-payment-type" v-model="taxSetupForm.etims_payment_type_code" class="field" maxlength="5" placeholder="Use the approved KRA code"><small v-if="taxSetupForm.errors.etims_payment_type_code" class="form-error">{{ taxSetupForm.errors.etims_payment_type_code }}</small></div>
                    <div class="form-field"><label for="etims-buyer-acceptance">Buyer acceptance</label><select id="etims-buyer-acceptance" v-model="taxSetupForm.etims_buyer_acceptance" class="select-field"><option value="Y">Buyer has accepted</option><option value="N">Buyer acceptance not recorded</option></select><small v-if="taxSetupForm.errors.etims_buyer_acceptance" class="form-error">{{ taxSetupForm.errors.etims_buyer_acceptance }}</small></div>
                </template>
                <div class="form-field"><label for="tax-accountant">Approving accountant / adviser</label><input id="tax-accountant" v-model="taxSetupForm.accountant_name" class="field" maxlength="255"></div>
                <div class="form-field"><label for="tax-approval-reference">Approval letter / source reference</label><input id="tax-approval-reference" v-model="taxSetupForm.accountant_approval_reference" class="field" maxlength="255"></div>
                <div class="form-field"><label for="tax-approval-date">Approval date</label><input id="tax-approval-date" v-model="taxSetupForm.accountant_approval_date" class="field" type="date"></div>
                <div class="form-actions"><button class="primary-button" type="submit" :disabled="taxSetupForm.processing"><Save aria-hidden="true" />{{ taxSetupForm.processing ? 'Saving…' : 'Save tax setup draft' }}</button></div>
                <div class="tax-category-heading"><h4>Supply tax categories</h4><button class="secondary-link compact-action" type="button" @click="addTaxCategory">Add category</button></div>
                <article v-for="(category, index) in taxSetupForm.categories" :key="index" class="tax-category-card">
                    <div class="form-field"><label :for="`tax-category-code-${index}`">Stable code</label><input :id="`tax-category-code-${index}`" v-model="category.code" class="field" maxlength="48"><small v-if="taxSetupForm.errors[`categories.${index}.code`]" class="form-error">{{ taxSetupForm.errors[`categories.${index}.code`] }}</small></div>
                    <div class="form-field"><label :for="`tax-category-label-${index}`">Supply name</label><input :id="`tax-category-label-${index}`" v-model="category.label" class="field" maxlength="120"><small v-if="taxSetupForm.errors[`categories.${index}.label`]" class="form-error">{{ taxSetupForm.errors[`categories.${index}.label`] }}</small></div>
                    <div class="form-field"><label :for="`tax-category-treatment-${index}`">Tax treatment</label><select :id="`tax-category-treatment-${index}`" v-model="category.treatment" class="select-field"><option value="unconfigured">Not classified</option><option value="taxable">Taxable</option><option value="zero_rated">Zero-rated</option><option value="exempt">Exempt</option><option value="out_of_scope">Out of scope</option></select></div>
                    <div class="form-field"><label :for="`tax-category-rate-${index}`">Rate (%)</label><input :id="`tax-category-rate-${index}`" v-model="category.rate" class="field" inputmode="decimal" placeholder="0.0000"><small v-if="taxSetupForm.errors[`categories.${index}.rate`]" class="form-error">{{ taxSetupForm.errors[`categories.${index}.rate`] }}</small></div>
                    <div class="form-field"><label :for="`tax-category-from-${index}`">Effective from</label><input :id="`tax-category-from-${index}`" v-model="category.effective_from" class="field" type="date"></div>
                    <div class="form-field"><label :for="`tax-category-to-${index}`">Effective to</label><input :id="`tax-category-to-${index}`" v-model="category.effective_to" class="field" type="date"></div>
                    <div class="form-field"><label :for="`tax-category-output-${index}`">Output tax account</label><input :id="`tax-category-output-${index}`" v-model="category.output_account_code" class="field" maxlength="16"></div>
                    <div class="form-field"><label :for="`tax-category-revenue-${index}`">Revenue account</label><input :id="`tax-category-revenue-${index}`" v-model="category.revenue_account_code" class="field" maxlength="16"></div>
                    <div class="form-field"><label :for="`tax-category-reference-${index}`">Accountant/source reference</label><input :id="`tax-category-reference-${index}`" v-model="category.basis_reference" class="field" maxlength="255"></div>
                    <div v-if="taxSetupForm.etims_solution === 'kra'" class="tax-category-etims-mapping">
                        <h5>KRA item mapping</h5>
                        <div class="finance-config-grid">
                            <div class="form-field"><label :for="`etims-tax-type-${index}`">KRA tax type</label><select :id="`etims-tax-type-${index}`" v-model="category.etims_tax_type_code" class="select-field"><option value="">Select approved code</option><option v-for="code in ['A', 'B', 'C', 'D', 'E']" :key="code" :value="code">{{ code }}</option></select></div>
                            <div class="form-field"><label :for="`etims-item-code-${index}`">KRA item code</label><input :id="`etims-item-code-${index}`" v-model="category.etims_item_code" class="field" maxlength="20"></div>
                            <div class="form-field"><label :for="`etims-class-code-${index}`">Item classification code</label><input :id="`etims-class-code-${index}`" v-model="category.etims_item_class_code" class="field" maxlength="10"></div>
                            <div class="form-field"><label :for="`etims-package-unit-${index}`">Package unit code</label><input :id="`etims-package-unit-${index}`" v-model="category.etims_packaging_unit_code" class="field" maxlength="5"></div>
                            <div class="form-field"><label :for="`etims-quantity-unit-${index}`">Quantity unit code</label><input :id="`etims-quantity-unit-${index}`" v-model="category.etims_quantity_unit_code" class="field" maxlength="5"></div>
                        </div>
                    </div>
